    LmP0Field * f2;
    const LmP0Node * node;
    const LmP0Frame * frame;
    const LmP0Text * name;
    char a[64];
    char b[64];
    char msg[256];
    char dep[64];
    LmP0Structure * fields;
    if (root == 0 || root -> kind != LM_P0_NODE_STRUCTURE) {
    return l1_error(path, root, "by-value cycle between structs; make one a pointer");
    }
    field = root -> as -> structure -> first_field;
    while (field != 0) {
    node = field -> value;
    if (l1_node_ignored(node) == 0 && node != 0 && node -> kind == LM_P0_NODE_FRAME && l1_text_eq(node->as->frame->head, "struct")) {
    frame = node -> as -> frame;
    name = l1_hdr_frame_name(frame);
    if (name != 0 && l1_ident_to_buf(a, 64U, name) == 0) {
    if (l1_hdr_name_list_has(l1_hdr_emitted, l1_hdr_emittedn, a) == 0) {
    fields = l1_hdr_fields_structure(frame);
    if (fields != 0) {
    f2 = fields -> first_field;
    while (f2 != 0) {
    if (l1_node_ignored(f2->value) == 0 && l1_hdr_field_byval_name(f2->value, dep, 64U) != 0) {
    if (l1_hdr_name_list_has(l1_hdr_emitted, l1_hdr_emittedn, dep) == 0) {
    snprintf(msg, 256U, "by-value cycle between struct %s and struct %s; make one a pointer", a, dep);
    return l1_error(path, node, msg);
    }
    }
    f2 = f2 -> next;
    }
    }
    }
    }
    }
    field = field -> next;
    }
    strcpy(msg, "by-value cycle between structs; make one a pointer");
